 1	package com.evo.cart.application.service.impl.command;
 2	
 3	import java.util.UUID;
 4	
 5	import org.springframework.security.core.context.SecurityContextHolder;
 6	import org.springframework.stereotype.Service;
 7	
 8	import com.evo.cart.application.dto.mapper.CartDTOMapper;
 9	import com.evo.cart.application.dto.request.UpdateCartRequest;
 10	import com.evo.cart.application.mapper.CommandMapper;
 11	import com.evo.cart.application.service.CartCommandService;
 12	import com.evo.cart.domain.Cart;
 13	import com.evo.cart.domain.command.UpdateCartCmd;
 14	import com.evo.cart.domain.repository.CartDomainRepository;
 15	import com.evo.cart.infrastructure.support.exception.AppErrorCode;
 16	import com.evo.cart.infrastructure.support.exception.AppException;
 17	import com.evo.common.dto.response.CartDTO;
...
 20	
 21	@Service
 22	@RequiredArgsConstructor
 23	public class CartCommandServiceImpl implements CartCommandService {
 24	 private final CartDomainRepository cartDomainRepository;
 25	 private final CommandMapper commandMapper;
 26	 private final CartDTOMapper cartDTOMapper;
 27	
 28	 @Override
 29	 public CartDTO getOrInitCart() {
 30	 var context = SecurityContextHolder.getContext();
 31	 UUID userId = UUID.fromString(context.getAuthentication().getName());
 32	
 33	 Cart cart = cartDomainRepository.getByUserIdOrNull(userId);
 34	 if (cart != null) {
 35	 return cartDTOMapper.domainModelToDTO(cart);
 36	 }
 37	 UpdateCartCmd updateCartCmd = UpdateCartCmd.builder().userId(userId).build();
 38	 cart = new Cart(updateCartCmd);
 39	 cart = cartDomainRepository.save(cart);
 40	 return cartDTOMapper.domainModelToDTO(cart);
 41	 }
 42	
 43	 @Override
 44	 public CartDTO updateCart(UpdateCartRequest request) {
 45	 UpdateCartCmd updateCartCmd = commandMapper.from(request);
 46	 Cart cart = cartDomainRepository.getById(updateCartCmd.getId());
 47	 if (cart == null) {
 48	 throw new AppException(AppErrorCode.CART_NOT_FOUND);
 49	 }
 50	 cart.update(updateCartCmd);
 51	 cart = cartDomainRepository.save(cart);
 52	 return cartDTOMapper.domainModelToDTO(cart);
 53	 }
 54	
 55	 @Override
 56	 public void emptyCart(UUID cartId) {
 57	 Cart cart = cartDomainRepository.getById(cartId);
 58	 cart.emptyCart();
 59	 cartDomainRepository.save(cart);
 60	 }
 61	}
