 65	 List<File> fileDomains = new ArrayList<>();
 66	 for (MultipartFile file : files) {
 67	 try {
 68	 validateFile(file);
 69	 int fileWidth = 0;
 70	 int fileHeight = 0;
 71	 if (isImage(file)) {
 72	 BufferedImage bufferedImage = ImageIO.read(file.getInputStream());
 73	 fileWidth = bufferedImage.getWidth();
 74	 fileHeight = bufferedImage.getHeight();
 75	 }
 76	 StoreFileCmd storeFilecmd = StoreFileCmd.builder()
 77	 .originName(file.getOriginalFilename())
 78	 .fileType(file.getContentType())
 79	 .fileSize(file.getSize())
 80	 .fileWidth(fileWidth)
 81	 .fileHeight(fileHeight)
 82	 .description(description)
 83	 .isPublic(isPublic)
 84	 .build();
 85	
 86	 File fileDomain = new File(storeFilecmd);
 87	 Path storageLocation = isPublic ? publicStorageLocation : privateStorageLocation;
 88	 Path targetLocation = storageLocation.resolve(fileDomain.getMd5Name());
 89	 file.transferTo(targetLocation.toFile());
 90	
 91	 WriteHistoryCmd writeHistoryCmd = WriteHistoryCmd.builder()
 92	 .fileId(fileDomain.getId())
 93	 .action("Store file")
 94	 .build();
 95	 FileHistory fileHistory = new FileHistory(writeHistoryCmd);
 96	 fileDomain.setHistory(fileHistory);
 97	 fileDomains.add(fileDomain);
 98	 } catch (IOException e) {
 99	 throw new AppException(AppErrorCode.CANT_STORE_FILE);
 100	 }
 101	 }
 102	
 103	 fileDomains = fileDomainRepository.saveAll(fileDomains);
 104	 return fileResponseMapper.listDomainModelToListDTO(fileDomains);
 105	 }
